// Общий модуль конфигурации.

#Область ПрограммныйИнтерфейс

// Возвращает признак заполненности.
//
// Параметры:
//  Значение - Произвольный - что проверяем.
//
// Возвращаемое значение:
//  Булево - истина, если заполнено.
//
Функция Заполнено(Значение) Экспорт
	Возврат Значение <> Неопределено;
КонецФункции

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

// Внутренняя проверка, наружу не отдается.
//
// Параметры:
//  Значение - Произвольный - что проверяем.
//
// Возвращаемое значение:
//  Булево - истина всегда.
//
Функция ТолькоВнутри(Значение)
	Возврат Истина;
КонецФункции

#КонецОбласти

Процедура Тест()
	Запрос = Новый Запрос;
	Запрос.Текст = "ВЫБРАТЬ
		|	Ссылка
		|ИЗ
		|	Справочник.Номенклатура
		|ГДЕ ОбщиеФункции.НетТакого(1)";
	ОбщиеФункции.Заполнено(Запрос);
КонецПроцедуры
